import itertools

alpha = 0.2
trigger = (48, 68)

def cascade_with_candidate(candidate):
    # Build the upgraded grid: original G plus the candidate edge
    H = G.copy()
    H.add_edge(*candidate)

    # Step 1 & 2: initial loads and capacities computed on the intact (upgraded) network
    loads_initial = nx.betweenness_centrality(H, normalized=False)
    cap = {n: (1 + alpha) * loads_initial.get(n, 0) for n in H.nodes()}

    # Step 3: trigger - remove the specified line if present
    if H.has_edge(*trigger):
        H.remove_edge(*trigger)

    # Step 4: iterative cascade
    current = H.copy()
    while True:
        loads = nx.betweenness_centrality(current, normalized=False)
        overloaded = [n for n in current.nodes() if loads.get(n, 0) > cap.get(n, 0)]
        if not overloaded:
            break
        current.remove_nodes_from(overloaded)

    # Step 5: determine survivors (largest connected component)
    if current.number_of_nodes() == 0:
        largest = set()
    else:
        largest = max(nx.connected_components(current), key=len)
    survivors_count = len(largest)
    return survivors_count, largest

candidates = [(31, 81), (23, 76), (48, 82)]
results = {}

for cand in candidates:
    size, comp = cascade_with_candidate(cand)
    results[cand] = {"size": size, "component": sorted(comp)}

for cand, res in results.items():
    print(f"Candidate {cand}: largest component size = {res['size']}, nodes = {res['component']}")

